import pandas as pd

def clean(df):
    df = df.copy()
    for col in df.columns:
        if df[col].dtype == object:
            df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Biscoe': 'Biscoe'})
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = (df['body_mass_g'].astype(str)
                             .str.replace(',', '', regex=False)
                             .str.strip())
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
        mask = (df['body_mass_g'] > 6500) & ((df['body_mass_g'] / 1000.0).between(2500, 6500))
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000.0
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df.drop_duplicates()
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['island'])
    counts = d.groupby('island', dropna=True).size()
    return {str(k): int(v) for k, v in counts.items()}
